window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4bcc111cb1a31287"]={"versions": [{"id": "FIG-4bcc111cb1a31287", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses der E2E-Bibliotheksfunktion <code>E2E_P04mProtect()</code> innerhalb des AUTOSAR E2E-Protokolls (Profil 4m). Das Diagramm visualisiert den sequenziellen Prüfschritt „Verify inputs of the protect function“ vor der eigentlichen Berechnung und Modifikation der Übertragungsdaten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Kontext:</strong> Funktion <code>E2E_P04mProtect()</code>.\n</li><li><strong>Eingangsparameter &amp; Prüfentitäten:</strong>\n<ul class=\"fig-list\"><li><code>Config</code>: Zeiger auf die statische Profil-Konfigurationsstruktur (u. a. <code>MinDataLength</code>, <code>MaxDataLength</code> in Bits).\n</li><li><code>State</code>: Zeiger auf die Zustandsstruktur der Schutzfunktion.\n</li><li><code>Data</code>: Zeiger auf das zu schützende Daten-Payload-Array.\n</li><li><code>Length</code>: Länge des zu schützenden Nutzdatenbereichs in Bytes.\n</li><li><code>SourceID</code>: 32-Bit-Quellidentifikator (darf maximal <code>0xFFFFFFF</code>, also 28 Bit, belegen).\n</li><li><code>MessageType</code>: Nachrichtentyp (Wertebereich 0 bis 1).\n</li><li><code>MessageResult</code>: Nachrichtenübertragungsergebnis (Wertebereich 0 bis 1).\n</li></ul>\n</li><li><strong>Ablaufelemente &amp; Endzustände:</strong>\n<ul class=\"fig-list\"><li>Startknoten (Initial Node).\n</li><li>Fünf Entscheidungsknoten (Decision Diamonds) mit <code>[TRUE]</code>- und <code>[FALSE]</code>-Guards.\n</li><li>Drei Ablaufendknoten (Activity Final Nodes): <code>null input</code>, <code>wrong input</code> und <code>input ok</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt über den Startknoten in den ersten Entscheidungsknoten:\n<ul class=\"fig-list\"><li>Bedingung: <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL)</code>.\n</li><li>Bei <code>[FALSE]</code>: Verzweigung zum Endknoten <code>null input</code> (Zeiger ungültig).\n</li></ul>\n</li><li>Bei <code>[TRUE]</code> Prüfung der Datenlänge:\n<ul class=\"fig-list\"><li>Bedingung: <code>(Length &gt;= Config-&gt;MinDataLength/8) &amp;&amp; (Length &lt;= Config-&gt;MaxDataLength/8)</code>.\n</li><li>Bei <code>[FALSE]</code>: Verzweigung zum Endknoten <code>wrong input</code>.\n</li></ul>\n</li><li>Bei <code>[TRUE]</code> Prüfung des Quellidentifikators:\n<ul class=\"fig-list\"><li>Bedingung: <code>SourceID &lt;= 0xFFFFFFF</code>.\n</li><li>Bei <code>[FALSE]</code>: Verzweigung zum Endknoten <code>wrong input</code>.\n</li></ul>\n</li><li>Bei <code>[TRUE]</code> Prüfung des Nachrichtentyps:\n<ul class=\"fig-list\"><li>Bedingung: <code>(MessageType &gt;= 0) &amp;&amp; (MessageType &lt;= 1)</code>.\n</li><li>Bei <code>[FALSE]</code>: Verzweigung zum Endknoten <code>wrong input</code>.\n</li></ul>\n</li><li>Bei <code>[TRUE]</code> Prüfung des Nachrichtenergebnisses:\n<ul class=\"fig-list\"><li>Bedingung: <code>(MessageResult &gt;= 0) &amp;&amp; (MessageResult &lt;= 1)</code>.\n</li><li>Bei <code>[FALSE]</code>: Verzweigung zum Endknoten <code>wrong input</code>.\n</li></ul>\n</li><li>Werden alle Bedingungen mit <code>[TRUE]</code> evaluiert, erreicht der Kontrollfluss den Endknoten <code>input ok</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normative Fehlerbehandlungsverhalten gemäß Anforderung <code>[PRS_E2E_00757]</code>. Für Implementierer ist zu beachten:</p>\n<ul class=\"fig-list\"><li>Zeigerprüfungen (<code>NULL</code>) besitzen strikte Priorität und führen direkt zur Klassifikation als Null-Eingabe (<code>null input</code> bzw. Rückgabewert <code>E2E_E_INPUTERR_NULL</code>).\n</li><li>Längen- und Wertebereichsverletzungen führen unmittelbar zu <code>wrong input</code> (<code>E2E_E_INPUTERR_WRONG</code>).\n</li><li>Die Konfigurationsgrenzen <code>MinDataLength</code> und <code>MaxDataLength</code> sind in Bit spezifiziert und müssen vor dem Vergleich mit <code>Length</code> ganzzahlig durch 8 dividiert werden.\n</li><li>Die Prüfungen brechen kaskadierend beim ersten Fehler ab (Short-Circuit-Verhalten im Aktivitätsfluss).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-7850640e8b01b547", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses der E2E-Bibliotheksfunktion <code>E2E_P04mProtect()</code> innerhalb des AUTOSAR E2E-Protokolls (Profil 4m). Das Diagramm visualisiert den sequenziellen Prüfschritt „Verify inputs of the protect function“ vor der eigentlichen Berechnung und Modifikation der Übertragungsdaten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Kontext:</strong> Funktion <code>E2E_P04mProtect()</code>.\n</li><li><strong>Eingangsparameter &amp; Prüfentitäten:</strong>\n<ul class=\"fig-list\"><li><code>Config</code>: Zeiger auf die statische Profil-Konfigurationsstruktur (u. a. <code>MinDataLength</code>, <code>MaxDataLength</code> in Bits).\n</li><li><code>State</code>: Zeiger auf die Zustandsstruktur der Schutzfunktion.\n</li><li><code>Data</code>: Zeiger auf das zu schützende Daten-Payload-Array.\n</li><li><code>Length</code>: Länge des zu schützenden Nutzdatenbereichs in Bytes.\n</li><li><code>SourceID</code>: 32-Bit-Quellidentifikator (darf maximal <code>0xFFFFFFF</code>, also 28 Bit, belegen).\n</li><li><code>MessageType</code>: Nachrichtentyp (Wertebereich 0 bis 1).\n</li><li><code>MessageResult</code>: Nachrichtenübertragungsergebnis (Wertebereich 0 bis 1).\n</li></ul>\n</li><li><strong>Ablaufelemente &amp; Endzustände:</strong>\n<ul class=\"fig-list\"><li>Startknoten (Initial Node).\n</li><li>Fünf Entscheidungsknoten (Decision Diamonds) mit <code>[TRUE]</code>- und <code>[FALSE]</code>-Guards.\n</li><li>Drei Ablaufendknoten (Activity Final Nodes): <code>null input</code>, <code>wrong input</code> und <code>input ok</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt über den Startknoten in den ersten Entscheidungsknoten:\n<ul class=\"fig-list\"><li>Bedingung: <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL)</code>.\n</li><li>Bei <code>[FALSE]</code>: Verzweigung zum Endknoten <code>null input</code> (Zeiger ungültig).\n</li></ul>\n</li><li>Bei <code>[TRUE]</code> Prüfung der Datenlänge:\n<ul class=\"fig-list\"><li>Bedingung: <code>(Length &gt;= Config-&gt;MinDataLength/8) &amp;&amp; (Length &lt;= Config-&gt;MaxDataLength/8)</code>.\n</li><li>Bei <code>[FALSE]</code>: Verzweigung zum Endknoten <code>wrong input</code>.\n</li></ul>\n</li><li>Bei <code>[TRUE]</code> Prüfung des Quellidentifikators:\n<ul class=\"fig-list\"><li>Bedingung: <code>SourceID &lt;= 0xFFFFFFF</code>.\n</li><li>Bei <code>[FALSE]</code>: Verzweigung zum Endknoten <code>wrong input</code>.\n</li></ul>\n</li><li>Bei <code>[TRUE]</code> Prüfung des Nachrichtentyps:\n<ul class=\"fig-list\"><li>Bedingung: <code>(MessageType &gt;= 0) &amp;&amp; (MessageType &lt;= 1)</code>.\n</li><li>Bei <code>[FALSE]</code>: Verzweigung zum Endknoten <code>wrong input</code>.\n</li></ul>\n</li><li>Bei <code>[TRUE]</code> Prüfung des Nachrichtenergebnisses:\n<ul class=\"fig-list\"><li>Bedingung: <code>(MessageResult &gt;= 0) &amp;&amp; (MessageResult &lt;= 1)</code>.\n</li><li>Bei <code>[FALSE]</code>: Verzweigung zum Endknoten <code>wrong input</code>.\n</li></ul>\n</li><li>Werden alle Bedingungen mit <code>[TRUE]</code> evaluiert, erreicht der Kontrollfluss den Endknoten <code>input ok</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normative Fehlerbehandlungsverhalten gemäß Anforderung <code>[PRS_E2E_00757]</code>. Für Implementierer ist zu beachten:</p>\n<ul class=\"fig-list\"><li>Zeigerprüfungen (<code>NULL</code>) besitzen strikte Priorität und führen direkt zur Klassifikation als Null-Eingabe (<code>null input</code> bzw. Rückgabewert <code>E2E_E_INPUTERR_NULL</code>).\n</li><li>Längen- und Wertebereichsverletzungen führen unmittelbar zu <code>wrong input</code> (<code>E2E_E_INPUTERR_WRONG</code>).\n</li><li>Die Konfigurationsgrenzen <code>MinDataLength</code> und <code>MaxDataLength</code> sind in Bit spezifiziert und müssen vor dem Vergleich mit <code>Length</code> ganzzahlig durch 8 dividiert werden.\n</li><li>Die Prüfungen brechen kaskadierend beim ersten Fehler ab (Short-Circuit-Verhalten im Aktivitätsfluss).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-4bcc111cb1a31287", "to": "FIG-7850640e8b01b547", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
